{
     "title": "CSCI-499: Computer Science Undergraduate Co-op Orientation",
     "learningObjectives": [
       "Students will define the minimum time commitment and registration requirements for the co-op program.",
       "Students will articulate the dual-document grading system and consistency standards for co-op evaluation.",
       "Students will apply ACM ethical principles and responsible research practices to professional co-op work."
     ],
     "beats": [
       {
         "title": "Program Overview and Status",
         "claim": "Students registered for the co-op program are considered to have full-time status by the institution.",
         "example": "A student enrolled in CSCI-499 for the fall semester is counted as a full-time undergraduate for financial aid and housing purposes.",
         "visualDirection": "Display a simple badge graphic labeled 'Full-Time Status' next to a calendar showing a 14-week span.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Time Commitment Requirements",
         "claim": "Students must work a minimum of 14 weeks and 35 hours per week to register for the co-op.",
         "example": "A student planning a spring co-op must schedule at least 490 hours of work spread across the semester.",
         "visualDirection": "Show a bar chart comparing a 14-week minimum schedule against a 12-week schedule, highlighting the 35-hour weekly threshold.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Prerequisite Coursework",
         "claim": "Students must complete CSCI-099 or an equivalent course before registering for the co-op.",
         "example": "A student who has not taken CSCI-099 must enroll in it first to become eligible for the co-op program.",
         "visualDirection": "Create a linear prerequisite flowchart: 'CSCI-099' -> 'Eligible for CSCI-499 Co-op'.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Student Work Report Requirement",
         "claim": "Students must complete a student co-op work report for each term they are registered for.",
         "example": "A student working on a software development project must submit a written report detailing their tasks, challenges, and outcomes.",
         "visualDirection": "Show a document template with sections for 'Project Description', 'Technical Implementation', and 'Learning Outcomes'.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Supervisor Evaluation Requirement",
         "claim": "Students are evaluated each term by their supervisor, and the evaluation must correspond to the student's work.",
         "example": "A supervisor reviews the student's code commits and deliverables to provide a formal performance evaluation.",
         "visualDirection": "Display a two-column comparison: 'Student Report' vs. 'Supervisor Evaluation' with a checkmark indicating consistency.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Grading Consistency Standard",
         "claim": "A satisfactory grade is awarded only when both documents are generally consistent and complete.",
         "example": "If the student report describes a database migration but the supervisor evaluation focuses solely on UI testing, the grade is not satisfactory.",
         "visualDirection": "Use a Venn diagram showing the overlap between 'Student Report Content' and 'Supervisor Evaluation Content' as the grading zone.",
         "sourceIds": ["rit-csci-499"]
       },
       {
         "title": "Ethical Computing Principles",
         "claim": "Computing professionals must avoid harm, be honest, and strive for high quality in processes and products.",
         "example": "A co-op student developing an AI model must audit training data for bias and document limitations to prevent harmful outcomes.",
         "visualDirection": "Present a checklist graphic with icons for 'Avoid Harm', 'Honesty', 'High Quality', and 'Respect Privacy'.",
         "sourceIds": ["acm-code-of-ethics"]
       },
       {
         "title": "Responsible Research Communication",
         "claim": "Technical communication must distinguish claims from evidence, cite prior work, and avoid fabrication or falsification.",
         "example": "A student's co-op report must include a literature review section that cites existing algorithms before presenting new results.",
         "visualDirection": "Show a side-by-side comparison of a 'Misleading Claim' (highlighted in red) versus a 'Responsible Claim' (highlighted in green) with citations.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Research Integrity and Transparency",
         "claim": "Authors should preserve research integrity by making limitations and threats to validity visible and disclosing conflicts.",
         "example": "A co-op project report must include a dedicated section listing data collection constraints and potential biases in the experimental setup.",
         "visualDirection": "Create a template slide with a 'Limitations & Threats' box and a 'Conflicts Disclosure' field to be filled by students.",
         "sourceIds": ["acm-research-practice"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students must verify registration eligibility, document consistency, ethical compliance, and research transparency before submitting co-op materials.",
         "example": "Before final submission, a student checks that their 14-week schedule is logged, their report matches the supervisor's evaluation, and all ethical guidelines are met.",
         "visualDirection": "Display a final checklist graphic with four checkboxes: '14-Week/35-Hr Commitment', 'Report-Evaluation Consistency', 'Ethical Compliance', 'Research Transparency'.",
         "sourceIds": ["rit-csci-499", "acm-code-of-ethics"]
       }
     ]
   }
